import { describe, it, expect } from "vitest";
import { readFileSync } from "fs";
import path from "path";
import { createHash } from "crypto";
import {
  buildCommonSetSnapshot,
  parseCommonSetSnapshot,
  SnapshotTooLargeError,
  SnapshotFormatError,
} from "@/lib/common-set-snapshot";

/**
 * Parity-seam golden fixture (CLAUDE.md): `common_set_snapshot_golden.json` is generated by
 * `ml/tests/fixtures/gen_common_set_snapshot_golden.py` (stdlib only, from the spec in
 * `docs/detection/common-set-snapshot-format.md`) and read by
 * `crates/ml/tests/common_set_snapshot_golden.rs`. If this builder drifts from the spec the
 * bytes differ and this fails without a live agent.
 */
type GoldenCase = {
  name: string;
  params: {
    min_hosts: number;
    hosts_covered: number;
    built_at: number;
    false_positive_rate: number;
    hashes: string[];
  };
  bytes_hex: string;
  members: string[];
  non_members: string[];
};

const golden: { format_version: number; cases: GoldenCase[] } = JSON.parse(
  readFileSync(
    path.join(__dirname, "../../../ml/tests/fixtures/common_set_snapshot_golden.json"),
    "utf8"
  )
);

const toHex = (b: Uint8Array) => Buffer.from(b).toString("hex");
const sha = (n: number) => n.toString(16).padStart(64, "0");
/** A real digest: the filter relies on the input being uniform, as SHA-256 output is. */
const digest = (n: number) => createHash("sha256").update(String(n)).digest("hex");

function build(c: GoldenCase) {
  return buildCommonSetSnapshot({
    hashes: c.params.hashes,
    minHosts: c.params.min_hosts,
    hostsCovered: c.params.hosts_covered,
    builtAt: c.params.built_at,
    falsePositiveRate: c.params.false_positive_rate,
  });
}

describe("common-set snapshot against the golden fixture", () => {
  for (const c of golden.cases) {
    it(`builds the reference bytes: ${c.name}`, () => {
      expect(toHex(build(c))).toBe(c.bytes_hex);
    });

    it(`parses the reference bytes and answers membership: ${c.name}`, () => {
      const snapshot = parseCommonSetSnapshot(Buffer.from(c.bytes_hex, "hex"));
      expect(snapshot.header).toMatchObject({
        formatVersion: golden.format_version,
        minHosts: c.params.min_hosts,
        hostsCovered: c.params.hosts_covered,
        builtAt: c.params.built_at,
      });
      for (const m of c.members) expect(snapshot.contains(m)).toBe(true);
      for (const n of c.non_members) expect(snapshot.contains(n)).toBe(false);
    });
  }
});

describe("buildCommonSetSnapshot", () => {
  const base = { minHosts: 3, hostsCovered: 5, builtAt: 1_791_849_600, falsePositiveRate: 0.01 };

  it("gives the same bytes for the same set in any order, with duplicates", () => {
    const a = buildCommonSetSnapshot({ ...base, hashes: [sha(1), sha(2), sha(3)] });
    const b = buildCommonSetSnapshot({ ...base, hashes: [sha(3), sha(1), sha(2), sha(1)] });
    expect(toHex(a)).toBe(toHex(b));
    expect(parseCommonSetSnapshot(a).header.entryCount).toBe(3);
  });

  it("never loses a member, at any size", () => {
    const hashes = Array.from({ length: 2000 }, (_, i) => digest(i));
    const snapshot = parseCommonSetSnapshot(buildCommonSetSnapshot({ ...base, hashes }));
    expect(hashes.filter((h) => !snapshot.contains(h))).toEqual([]);
  });

  it("stays near the target false-positive rate", () => {
    const hashes = Array.from({ length: 2000 }, (_, i) => digest(i));
    const snapshot = parseCommonSetSnapshot(
      buildCommonSetSnapshot({ ...base, hashes, falsePositiveRate: 0.01 })
    );
    const probes = Array.from({ length: 20000 }, (_, i) => digest(1_000_000 + i));
    const rate = probes.filter((h) => snapshot.contains(h)).length / probes.length;
    expect(rate).toBeLessThan(0.02);
  });

  it("normalizes hashes the way the counters do and drops what is not a hash", () => {
    const upper = sha(255).toUpperCase();
    const snapshot = parseCommonSetSnapshot(
      buildCommonSetSnapshot({ ...base, hashes: [` ${upper} `, "not-a-hash", ""] })
    );
    expect(snapshot.header.entryCount).toBe(1);
    expect(snapshot.contains(sha(255))).toBe(true);
  });

  it("refuses to build past the byte cap instead of truncating", () => {
    const hashes = Array.from({ length: 5000 }, (_, i) => sha(i + 1));
    expect(() => buildCommonSetSnapshot({ ...base, hashes, maxBytes: 1024 })).toThrow(
      SnapshotTooLargeError
    );
  });

  it("rejects out-of-range parameters", () => {
    for (const bad of [0, 1, -0.5, Number.NaN]) {
      expect(() =>
        buildCommonSetSnapshot({ ...base, hashes: [sha(1)], falsePositiveRate: bad })
      ).toThrow(RangeError);
    }
    expect(() => buildCommonSetSnapshot({ ...base, hashes: [], minHosts: 0 })).toThrow(RangeError);
  });
});

describe("parseCommonSetSnapshot", () => {
  const good = () =>
    Buffer.from(
      buildCommonSetSnapshot({
        hashes: [sha(1), sha(2)],
        minHosts: 3,
        hostsCovered: 4,
        builtAt: 1,
        falsePositiveRate: 0.01,
      })
    );

  it("rejects a bad magic, an unknown version, a bad size and a wrong length", () => {
    const badMagic = good();
    badMagic[0] = 0x58;
    const badVersion = good();
    badVersion.writeUInt16LE(2, 4);
    const zeroHashes = good();
    zeroHashes.writeUInt16LE(0, 6);
    const oddBits = good();
    oddBits.writeUInt32LE(oddBits.readUInt32LE(20) + 1, 20);
    for (const bytes of [
      badMagic,
      badVersion,
      zeroHashes,
      oddBits,
      good().subarray(0, 31),
      good().subarray(0, good().length - 1),
      Buffer.concat([good(), Buffer.from([0])]),
      Buffer.alloc(0),
    ]) {
      expect(() => parseCommonSetSnapshot(bytes)).toThrow(SnapshotFormatError);
    }
  });
});
